import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  // Validate issueDate is a real date in YYYY-MM-DD format
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
  const [year, month, day] = issueDate.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return fail('UNKNOWN_SKU');

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a single invoice line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate invoice totals.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return { subtotal, total: subtotal };
}

/**
 * Add a line to a draft invoice, or increase qty if SKU already exists.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number }} line
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate SKU exists and get product details
  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  const product = productResult.value;

  // Check if SKU already exists on invoice
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  let newLines;

  if (existingLineIndex >= 0) {
    // Update qty of existing line
    newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex ? { ...line, qty: line.qty + qty } : line
    );
  } else {
    // Add new line at the end
    newLines = [...invoice.lines, {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    }];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line exists
  const lineExists = invoice.lines.some((line) => line.sku === sku);
  if (!lineExists) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Remove the line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

