  );
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2 },
